            if domain in domain_to_company {
                new_company = domain_to_company[domain]
                company_filled = true
            }
        }
    }

    updated = false
    if phone_fixed or company_filled {
        args = { id: contact.id }
        args = args + { phone: new_phone } if phone_fixed else args
        args = args + { company: new_company } if company_filled else args
        u = update_contact(args)
        updated = true
    }

    return { phone_fixed, company_filled }
}

